FUNCTION_BLOCK FB_Llenado
VAR_INPUT
    nivelAlto : BOOL; (* Sensor de nivel alto *)
    nivelBajo : BOOL; (* Sensor de nivel bajo *)
    btnInicio : BOOL; (* Botón de inicio del proceso *)
    btnParo : BOOL;   (* Botón de paro del proceso *)
END_VAR
VAR_OUTPUT
    vLlenado : BOOL;  (* Válvula de llenado *)
    motorMezcla : BOOL; (* Motor de mezcla *)
    vDescarga : BOOL; (* Válvula de descarga *)
END_VAR
VAR
    estado : INT := 0; (* Estado del proceso *)
    tMezcla : TON;     (* Temporizador para el motor de mezcla *)
END_VAR

(* Lógica del proceso de llenado por etapas *)
IF btnParo THEN
    (* Si se presiona el botón de paro, detener todo y volver a reposo *)
    estado := 0;
    vLlenado := FALSE;
    motorMezcla := FALSE;
    vDescarga := FALSE;
ELSE
    CASE estado OF
        0: (* Estado de reposo *)
            IF btnInicio THEN
                estado := 1; (* Iniciar proceso de llenado *)
            END_IF;
        1: (* Llenado *)
            vLlenado := TRUE;
            IF nivelAlto THEN
                vLlenado := FALSE;
                estado := 2; (* Pasar al estado de mezcla *)
                tMezcla(IN := TRUE, PT := T#60S); (* Iniciar temporizador de mezcla *)
            END_IF;
        2: (* Mezcla *)
            motorMezcla := TRUE;
            IF tMezcla.Q THEN
                motorMezcla := FALSE;
                estado := 3; (* Pasar al estado de descarga *)
            END_IF;
        3: (* Descarga *)
            vDescarga := TRUE;
            IF nivelBajo THEN
                vDescarga := FALSE;
                estado := 0; (* Volver al estado de reposo *)
            END_IF;
    END_CASE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Llenado
VAR_INPUT
    nivelAlto  : BOOL; (* Sensor de nivel alto *)
    nivelBajo  : BOOL; (* Sensor de nivel bajo *)
    btnInicio  : BOOL; (* Botón de inicio del proceso *)
    btnParo    : BOOL; (* Botón de paro de emergencia *)
END_VAR

VAR_OUTPUT
    vLlenado    : BOOL; (* Válvula de llenado *)
    motorMezcla : BOOL; (* Motor de mezcla *)
    vDescarga   : BOOL; (* Válvula de descarga *)
END_VAR

VAR
    (* Etapas del proceso *)
    eEtapa : INT := 0;
    (*
        0 = Reposo
        1 = Llenado
        2 = Mezcla
        3 = Descarga
    *)

    (* Temporizador para la etapa de mezcla *)
    tonMezcla : TON;
END_VAR

(* ─────────────────────────────────────────────
   Lógica principal
   ───────────────────────────────────────────── *)

(* Paro de emergencia: tiene prioridad sobre cualquier etapa *)
IF btnParo THEN
    eEtapa      := 0;
    vLlenado    := FALSE;
    motorMezcla := FALSE;
    vDescarga   := FALSE;
    tonMezcla(IN := FALSE, PT := T#60S); (* Reinicia temporizador *)

ELSE

    CASE eEtapa OF

        (* ── Etapa 0: Reposo ── *)
        0:
            vLlenado    := FALSE;
            motorMezcla := FALSE;
            vDescarga   := FALSE;
            tonMezcla(IN := FALSE, PT := T#60S);

            IF btnInicio THEN
                eEtapa := 1; (* Ir a llenado *)
            END_IF;

        (* ── Etapa 1: Llenado ── *)
        1:
            vLlenado    := TRUE;
            motorMezcla := FALSE;
            vDescarga   := FALSE;

            IF nivelAlto THEN
                vLlenado := FALSE;
                eEtapa   := 2; (* Ir a mezcla *)
            END_IF;

        (* ── Etapa 2: Mezcla (60 s) ── *)
        2:
            vLlenado    := FALSE;
            motorMezcla := TRUE;
            vDescarga   := FALSE;

            (* Activa el temporizador mientras se está en esta etapa *)
            tonMezcla(IN := TRUE, PT := T#60S);

            IF tonMezcla.Q THEN
                motorMezcla := FALSE;
                tonMezcla(IN := FALSE, PT := T#60S); (* Reinicia para próximo ciclo *)
                eEtapa := 3; (* Ir a descarga *)
            END_IF;

        (* ── Etapa 3: Descarga ── *)
        3:
            vLlenado    := FALSE;
            motorMezcla := FALSE;
            vDescarga   := TRUE;

            IF nivelBajo THEN
                vDescarga := FALSE;
                eEtapa    := 0; (* Volver a reposo *)
            END_IF;

        (* ── Estado no definido: ir a reposo de forma segura ── *)
        ELSE
            eEtapa      := 0;
            vLlenado    := FALSE;
            motorMezcla := FALSE;
            vDescarga   := FALSE;

    END_CASE;

END_IF;

