        vLlenado := FALSE;
        motorMezcla := FALSE;
        vDescarga := FALSE;
        IF btnInicio THEN
            estado := 1;
        END_IF

    1: // Llenado
        vLlenado := TRUE;
        IF nivelAlto THEN
            vLlenado := FALSE;
            estado := 2;
            timerMezcla(IN := TRUE, PT := T#60S);
        END_IF

    2: // Mezcla
        motorMezcla := TRUE;
        timerMezcla(IN := TRUE);
        IF timerMezcla.Q THEN
            motorMezcla := FALSE;
            estado := 3;
        END_IF

    3: // Descarga
        vDescarga := TRUE;
        IF nivelBajo THEN
            vDescarga := FALSE;
            estado := 0;
        END_IF
END_CASE

// Lógica de paro de emergencia
IF btnParo THEN
    vLlenado := FALSE;
    motorMezcla := FALSE;
    vDescarga := FALSE;
    estado := 0;
END_IF

